begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('30000000-0000-0000-0000-00000000000'||n)::uuid,'review-sql-'||n||'@example.invalid',jsonb_build_object('username','ReviewSQL'||n) from generate_series(1,5) n;
insert into auth.sessions(id,user_id) select id,id from public.profiles where id::text like '30000000-%';
update private.authz set role='critic' where user_id='30000000-0000-0000-0000-000000000003';
update private.authz set role='moderator' where user_id='30000000-0000-0000-0000-000000000004';
update private.authz set role='admin' where user_id='30000000-0000-0000-0000-000000000005';
insert into public.manual_games(id,title,synopsis,platforms,genres,source_url,source_label) values('30000000-0000-0000-0000-000000000099','Isolated SQL review fixture','Isolated SQL fixture only, never catalog data.',array['PC'],array['Test'],'https://example.com/isolated-review-sql','Isolated test');
create temp table review_input(data jsonb);
insert into review_input values('{"rating":7,"title":"Reseña SQL","bodyPublic":"Una aventura con combate preciso y exploración.","bodySpoiler":"El final secreto","pros":["Combate"],"cons":[]}');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000004','30000000-0000-0000-0000-000000000004','create','manual:30000000-0000-0000-0000-000000000099',null,data) from review_input$$,'42501',null,'role 4 cannot author');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000005','30000000-0000-0000-0000-000000000005','create','manual:30000000-0000-0000-0000-000000000099',null,data) from review_input$$,'42501',null,'role 5 cannot author');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002','create','manual:30000000-0000-0000-0000-000000000099',null,data) from review_input$$,'42501',null,'session must belong to actor');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','create','offline-slug',null,data) from review_input$$,'22023',null,'offline game denied');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','create','rawg:999999999',null,data) from review_input$$,'22023',null,'nonexistent RAWG denied');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','create','manual:30000000-0000-0000-0000-000000000098',null,data) from review_input$$,'22023',null,'nonexistent manual denied');
select lives_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','create','manual:30000000-0000-0000-0000-000000000099',null,data) from review_input$$,'ordinary user publishes without ten hour wait');
select is((select count(*)::int from public.reviews where author_id='30000000-0000-0000-0000-000000000001'),1,'one identity');
select is((select count(*)::int from private.audit_logs where actor_id='30000000-0000-0000-0000-000000000001' and action='review.create'),1,'one audit');
select ok((select target_id='30000000-0000-0000-0000-000000000001'::uuid and after_data ? 'reviewId' and not after_data ? 'bodyPublic' from private.audit_logs where actor_id='30000000-0000-0000-0000-000000000001' and action='review.create'),'private minimal audit with user target and review ID');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','create','manual:30000000-0000-0000-0000-000000000099',null,data) from review_input$$,'23505',null,'duplicate rejected');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000002','update','manual:30000000-0000-0000-0000-000000000099',1,data) from review_input$$,'P0002',null,'third party cannot edit owner');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',9,data) from review_input$$,'40001',null,'obsolete version rejected');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"rating":8}') from review_input$$,'22023',null,'rating only');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"rating":8,"title":"New title","bodySpoiler":"Different spoiler"}') from review_input$$,'22023',null,'title and spoiler only');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||jsonb_build_object('rating',8,'bodyPublic','  Una  aventura con combate preciso y exploración.  ')) from review_input$$,'22023',null,'whitespace opinion');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||jsonb_build_object('rating',8,'bodyPublic',replace(data->>'bodyPublic',' ',chr(160)))) from review_input$$,'22023',null,'Unicode whitespace opinion');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"rating":-1}') from review_input$$,'22023',null,'rating low');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"rating":11}') from review_input$$,'22023',null,'rating high');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"rating":"NaN"}') from review_input$$,'22023',null,'rating string');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"title":"aa"}') from review_input$$,'22023',null,'title short');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||jsonb_build_object('title',repeat('a',121))) from review_input$$,'22023',null,'title long');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"bodyPublic":"short"}') from review_input$$,'22023',null,'opinion short');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||jsonb_build_object('bodyPublic',repeat('a',10001))) from review_input$$,'22023',null,'opinion long');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||jsonb_build_object('bodySpoiler',repeat('a',20001))) from review_input$$,'22023',null,'spoiler long');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"pros":[null]}') from review_input$$,'22023',null,'null point');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"cons":["a","b","c","d","e","f"]}') from review_input$$,'22023',null,'too many points');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||jsonb_build_object('pros',jsonb_build_array(repeat('a',201)))) from review_input$$,'22023',null,'point long');
select lives_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data||'{"rating":8,"bodyPublic":"Una segunda lectura aporta detalles y mejoras interesantes."}') from review_input$$,'coordinated update');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',1,data) from review_input$$,'40001',null,'old version rejected after update');
select is((select version from public.reviews where author_id='30000000-0000-0000-0000-000000000001'),2,'server increments version');
select is(private.review_normalize(chr(65279)||'a'||chr(65279)||'b'||chr(65279)),'a b','normalize ECMAScript BOM whitespace too');
select lives_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','withdraw','manual:30000000-0000-0000-0000-000000000099',2,null) from review_input$$,'withdraw same identity');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','create','manual:30000000-0000-0000-0000-000000000099',null,data) from review_input$$,'23505',null,'withdrawn identity cannot duplicate');
set local role anon;
select is((select count(*)::int from public.reviews where author_id='30000000-0000-0000-0000-000000000001'),0,'withdrawn invisible to visitor');
reset role;
select is((private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','own','manual:30000000-0000-0000-0000-000000000099')->>'status'),'withdrawn','active owner reads withdrawn');
select lives_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','republish','manual:30000000-0000-0000-0000-000000000099',3,null) from review_input$$,'republish same row');
select is((select count(*)::int from public.reviews where author_id='30000000-0000-0000-0000-000000000001'),1,'republish retains identity');
update private.authz set status='suspended' where user_id='30000000-0000-0000-0000-000000000001';
set local role anon;
select is((select count(*)::int from public.reviews where author_id='30000000-0000-0000-0000-000000000001'),0,'suspension immediately hides public review');
reset role;
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','own','manual:30000000-0000-0000-0000-000000000099',null,null) from review_input$$,'42501',null,'suspended owner cannot read private');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',4,data) from review_input$$,'42501',null,'suspended owner cannot edit');
update private.authz set status='active' where user_id='30000000-0000-0000-0000-000000000001';
create function pg_temp.fail_review_audit() returns trigger language plpgsql as $$begin raise exception 'Isolated review audit failure'; end;$$;
create trigger isolated_review_audit_fault before insert on private.audit_logs for each row execute function pg_temp.fail_review_audit();
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',4,data) from review_input$$,'P0001',null,'audit failure rolls back mutation');
select is((select version from public.reviews where author_id='30000000-0000-0000-0000-000000000001'),4,'failed audit leaves version untouched');
drop trigger isolated_review_audit_fault on private.audit_logs;
update public.reviews set status='hidden' where author_id='30000000-0000-0000-0000-000000000001';
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',4,data) from review_input$$,'42501',null,'moderated content blocks update');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','withdraw','manual:30000000-0000-0000-0000-000000000099',4,data) from review_input$$,'42501',null,'moderated content blocks withdraw');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','republish','manual:30000000-0000-0000-0000-000000000099',4,data) from review_input$$,'42501',null,'moderated content blocks republish');
delete from auth.sessions where user_id='30000000-0000-0000-0000-000000000001';
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','own','manual:30000000-0000-0000-0000-000000000099',null,null) from review_input$$,'42501',null,'revoked session cannot read own');
select throws_ok($$select private.review_operation('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','update','manual:30000000-0000-0000-0000-000000000099',4,data) from review_input$$,'42501',null,'revoked session cannot write');
select throws_ok($$insert into public.reviews(author_id,game_id,manual_game_id,rating,title,body_public,author_active) values('30000000-0000-0000-0000-000000000002',null,null,7,'Title','An isolated public opinion with sufficient content.',true)$$,'23514',null,'XOR requires a game');
select throws_ok($$insert into public.reviews(author_id,game_id,manual_game_id,rating,title,body_public,author_active) values('30000000-0000-0000-0000-000000000002','rawg:999999999','30000000-0000-0000-0000-000000000099',7,'Title','An isolated public opinion with sufficient content.',true)$$,'23514',null,'XOR rejects both game IDs');
select throws_ok($$insert into public.reviews(author_id,game_id,manual_game_id,rating,title,body_public,author_active) values('30000000-0000-0000-0000-000000000002','rawg:999999999',null,7,'Title','An isolated public opinion with sufficient content.',true)$$,'23503',null,'RAWG FK checks existence');
select throws_ok($$insert into public.reviews(author_id,game_id,manual_game_id,rating,title,body_public,author_active) values('30000000-0000-0000-0000-000000000002',null,'30000000-0000-0000-0000-000000000098',7,'Title','An isolated public opinion with sufficient content.',true)$$,'23503',null,'manual FK checks existence');
set local role anon;
select throws_ok($$insert into public.reviews(title) values('forged')$$,'42501',null,'anon denies insert');
select throws_ok($$update public.reviews set rating=10$$,'42501',null,'anon denies update');
select throws_ok($$delete from public.reviews$$,'42501',null,'anon denies delete');
select throws_ok($$select private.review_operation(null,null,'create','rawg:1',null,'{}')$$,'42501',null,'anon denies private RPC');
select throws_ok($$select private.sync_review_author_status()$$,'42501',null,'anon denies trigger execution');
select throws_ok($$select * from private.audit_logs$$,'42501',null,'anon denies audit read');
reset role;
set local role authenticated;
select throws_ok($$insert into public.reviews(title) values('forged')$$,'42501',null,'authenticated denies insert');
select throws_ok($$update public.reviews set rating=10$$,'42501',null,'authenticated denies update');
select throws_ok($$delete from public.reviews$$,'42501',null,'authenticated denies delete');
select throws_ok($$select private.review_operation(null,null,'create','rawg:1',null,'{}')$$,'42501',null,'authenticated denies private RPC');
select throws_ok($$select private.sync_review_author_status()$$,'42501',null,'authenticated denies trigger execution');
select throws_ok($$select * from private.audit_logs$$,'42501',null,'authenticated denies audit read');
reset role;
set local role service_role;
select throws_ok($$insert into public.reviews(title) values('forged')$$,'42501',null,'service_role denies insert');
select throws_ok($$update public.reviews set rating=10$$,'42501',null,'service_role denies update');
select throws_ok($$delete from public.reviews$$,'42501',null,'service_role denies delete');
select throws_ok($$select private.review_operation(null,null,'create','rawg:1',null,'{}')$$,'42501',null,'service_role denies private RPC');
select throws_ok($$select private.sync_review_author_status()$$,'42501',null,'service_role denies trigger execution');
select throws_ok($$select * from private.audit_logs$$,'42501',null,'service_role denies audit read');
reset role;
select * from finish();
rollback;
